<template><div class="app-container"><el-card><template #header>{{props.title}}</template><el-button type="primary" @click="load">查询</el-button><el-button type="warning" @click="refresh">刷新网关路由</el-button><el-table v-loading="loading" :data="rows" border><el-table-column v-for="c in props.columns" :key="c.prop" :prop="c.prop" :label="c.label"><template #default="s">{{display(s.row[c.prop])}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-card></div></template>
<script setup>import{ElMessage}from'element-plus';import{pageConfigs,toCrudProps}from'@/views/pageConfig';import{useCrudPage}from'@/views/useCrudPage';import{pageApi}from'./api';const props=toCrudProps(pageConfigs.route,pageApi,{fetch:'routes',remove:'deleteRoute'});const{loading,rows,display,load,remove}=useCrudPage(props);async function refresh(){await pageApi.refreshRoutes();ElMessage.success('网关路由已刷新');load()}</script>
